export function heldOn(holds: readonly HoldView[], date: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

/** A past retirement of a person, from its from-date to the day they were unretired (yyyy-mm-dd). */
export interface RetirementView {
  from: string;
  to: string;
}

export interface PersonView {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the store answered. */
  grade: Grade;
  /** Every grade the person was given, the one from the beginning of time first, then by from-date. */
  grades: GradeView[];
  /** Bumped on each save; an edit is sent with the version its editor loaded. */
  version: number;
  /** True as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from, or null while they are not retired. */
  retiredFrom: string | null;
  /** Every past retirement of the person, in the order they were unretired. */
  retirements: RetirementView[];
  /** Whether the person has any hold, whatever its dates. */
  held: boolean;
  /** Every hold put on the person, by from-date: their open claims dated within one, unless a
   *  statement binds them, count in no live total. */
  holds: HoldView[];
  /** The ids of the other people on the sheet the person has named as patrons, in the order named. */
  patronIds: number[];
  /** Whether the signed-in user watches the person. */
  watched: boolean;
  /** The person's own terms, in days, or null when they use their grade's, else the sheet's. */
  terms: number | null;
  /** The person's contact, trimmed and lower-cased, or null when they have none. */
  contact: string | null;
  /** The other names the person is found by, sorted as names are compared. */
  aliases: string[];
  /** Whether a name or alias of theirs is used on another sheet of the sheet's tree. */
  clashing: boolean;
  /** The sheet the person was transferred from, or null when they were added on this sheet. */
  origin: string | null;
  /** The person's tags, lower-cased and sorted; empty when they have none. */
  tags: string[];
                <td data-testid="person-active">{{ activeIds().has(p.id) ? 'yes' : 'no' }}</td>
                <td>
                  <span data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</span>
                  from <span data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</span>
                  <label [for]="'person-retire-date-' + p.id" class="visually-hidden">Retire {{ p.name }} from</label>
                  <input type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date"
                    #retireDate (input)="clearPersonError(p.id)" />
                  <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
                    [disabled]="retiring() === p.id" [attr.aria-label]="'Retire ' + p.name">Retire</button>
                  <button type="button" data-testid="person-unretire" (click)="unretire(p)"
                    [disabled]="retiring() === p.id" [attr.aria-label]="'Unretire ' + p.name">Unretire</button>
                  @for (r of p.retirements; track $index) {
                    <div data-testid="person-retirement-line">{{ r.from }} to {{ r.to }}</div>
                  }
                </td>
                <td>
                  <span data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</span>
                  <ul [attr.aria-label]="'Holds on ' + p.name">
                    @for (h of p.holds; track $index) {
                      <li data-testid="person-hold-line">{{ h.from ?? 'the start' }} to {{ h.to ?? 'no end' }}</li>
                    }
                  </ul>
                  <label [for]="'person-hold-from-' + p.id" class="visually-hidden">Hold {{ p.name }} from</label>
                  <input type="date" [id]="'person-hold-from-' + p.id" data-testid="person-hold-from"
                    #holdFrom (input)="clearPersonError(p.id)" />
                  <label [for]="'person-hold-to-' + p.id" class="visually-hidden">Hold {{ p.name }} to</label>

